:root {
  --bg-tag: #f2ead8;
  --bg-header: #2b3a4a;
  --bg-footer: #3d2e1e;
  --accent-gold: #c9a84c;
  --accent-rust: #a0522d;
  --text-dark: #1e1612;
  --text-mid: #4a3b2c;
  --text-light: #f2ead8;
  --text-muted: #9e8c7a;
  --border-tag: #b8a87a;
  --spec-stripe: #e8dfc8;
}

.eyepiece-tag {
  width: 400px;
  border: 2px solid var(--border-tag);
  border-radius: 6px;
  overflow: hidden;
  margin: 20px auto;
  background-color: var(--bg-tag);
}

.tag-header {
  background-color: var(--bg-header);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 14px;
}

.tag-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2.5px;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.tag-number {
  font-size: 11px;
  font-weight: 400;
  color: var(--text-light);
  letter-spacing: 1px;
  opacity: 0.8;
}

.tag-body {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 14px;
  padding: 16px 16px 12px;
}

.eyepiece-icon {
  font-size: 40px;
  line-height: 1;
  flex-shrink: 0;
  padding-top: 4px;
}

.tag-details {
  flex: 1;
}

.eyepiece-name {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-dark);
  margin: 0 0 2px;
  letter-spacing: 0.5px;
}

.eyepiece-type {
  font-size: 12px;
  font-weight: 400;
  color: var(--accent-rust);
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin: 0 0 10px;
}

.spec-list {
  list-style: none;
  margin: 0;
  padding: 0;
  border: 1px solid var(--border-tag);
  border-radius: 4px;
  overflow: hidden;
}

.spec-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 5px 10px;
  font-size: 13px;
}

.spec-list li:nth-child(even) {
  background-color: var(--spec-stripe);
}

.spec-key {
  color: var(--text-mid);
  font-weight: 600;
}

.spec-val {
  color: var(--text-dark);
  font-weight: 400;
}

.tag-footer {
  background-color: var(--bg-footer);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 7px 14px;
}

.tag-condition {
  font-size: 11px;
  font-weight: 700;
  color: var(--accent-gold);
  letter-spacing: 1px;
}

.tag-date {
  font-size: 11px;
  color: var(--text-light);
  opacity: 0.75;
  letter-spacing: 0.5px;
}
